class Solution {
    public int nthSuperUglyNumber(int n,int[] primes){
        int[] ugly=new int[n],pointers=new int[primes.length];
        ugly[0]=1;
        for(int index=1;index<n;index++){
            long next=Long.MAX_VALUE;
            for(int i=0;i<primes.length;i++)next=Math.min(next,(long)ugly[pointers[i]]*primes[i]);
            ugly[index]=(int)next;
            for(int i=0;i<primes.length;i++)if((long)ugly[pointers[i]]*primes[i]==next)pointers[i]++;
        }
        return ugly[n-1];
    }
}

code.kotlin:
class Solution {
    fun nthSuperUglyNumber(n:Int,primes:IntArray):Int{
        val ugly=IntArray(n);
        val pointers=IntArray(primes.size);
        ugly[0]=1;
        for(index in 1 until n){
            var next=Long.MAX_VALUE;
            for(i in primes.indices)next=minOf(next,ugly[pointers[i]].toLong()*primes[i]);
            ugly[index]=next.toInt();
            for(i in primes.indices)if(ugly[pointers[i]].toLong()*primes[i]==next)pointers[i]++
        };
        return ugly.last()
    }
}

